<?php
require_once __DIR__.'/inc/common.php';require_employee();
$id=filter_input(INPUT_GET,'request',FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('Yêu cầu không hợp lệ');}
$q=db()->prepare('SELECT r.*,c.customer_code,c.full_name,c.phone,c.cccd,c.license_number,c.license_expiry,c.profile_valid,c.rental_allowed,c.unpaid_fee,m.model_code,m.model_name FROM rental_requests r JOIN customers c ON c.id=r.customer_id JOIN car_models m ON m.id=r.model_id WHERE r.id=?');$q->execute([$id]);$r=$q->fetch();if(!$r){http_response_code(404);exit('Không có yêu cầu');}
if($r['status']!=='CHO_XU_LY')go('contracts.php');
$v=db()->prepare("SELECT v.id,v.car_code,v.license_plate,v.model_id,m.model_name,m.daily_rate FROM cars v JOIN car_models m ON m.id=v.model_id WHERE v.status='SAN_SANG' ORDER BY (v.model_id=?) DESC,v.id");$v->execute([$r['model_id']]);$cars=$v->fetchAll();$hasRequested=count(array_filter($cars,fn($c)=>(int)$c['model_id']===(int)$r['model_id']))>0;
$profileOk=$r['profile_valid'] && trim($r['full_name'])!=='' && trim($r['phone'])!=='' && trim($r['cccd'])!=='' && trim($r['license_number'])!=='';
$licenseOk=$r['license_expiry']>=date('Y-m-d');$allowed=$r['rental_allowed'];$debtOk=(float)$r['unpaid_fee']<=0;
page_start('Lập hợp đồng'); ?>
<a class="back" href="index.php">← Trở về yêu cầu</a><div class="heading"><div><span class="eyebrow">UC27 / LẬP HỢP ĐỒNG</span><h1><?=esc($r['request_code'])?> · <?=esc($r['model_name'])?></h1><p>Thông tin khách hàng được lấy tự động từ hồ sơ đã lưu.</p></div></div>
<div class="twocol"><section class="card"><h2>01 · Hồ sơ khách hàng</h2><div class="detail"><span>Mã khách hàng</span><strong><?=esc($r['customer_code'])?></strong><span>Họ và tên</span><strong><?=esc($r['full_name'])?></strong><span>Số điện thoại</span><strong><?=esc($r['phone'])?></strong><span>CCCD</span><strong><?=esc($r['cccd'])?></strong><span>Giấy phép lái xe</span><strong><?=esc($r['license_number'])?></strong><span>Hạn GPLX</span><strong><?=esc($r['license_expiry'])?></strong><span>Phí chưa thanh toán</span><strong><?=money($r['unpaid_fee'])?></strong></div><div class="checks"><?php foreach([['Hồ sơ hợp lệ',$profileOk],['GPLX còn hiệu lực',$licenseOk],['Được phép thuê xe',$allowed],['Không còn phí chưa thanh toán',$debtOk]] as [$name,$ok]):?><div class="check <?= $ok?'ok':'bad' ?>"><?= $ok?'✓':'!' ?> <?=esc($name)?></div><?php endforeach;?></div><?php if(!$profileOk || !$licenseOk || !$allowed || !$debtOk):?><div class="alert error">Chưa đủ điều kiện lập hợp đồng. Cần cập nhật hồ sơ/GPLX hoặc xử lý khoản phí trong nghiệp vụ tương ứng, sau đó tải lại trang. Không nhập lại toàn bộ hồ sơ tại đây. <a href="customer_profile.php?id=<?=intval($r['customer_id'])?>">Cập nhật hồ sơ</a> · <a href="fee_payment.php?id=<?=intval($r['customer_id'])?>">Xử lý khoản phí</a></div><?php endif;?></section>
<section class="card"><h2>02 · Thông tin thuê xe</h2><?php if(!$hasRequested):?><div class="alert warn">Mẫu xe yêu cầu hiện hết xe sẵn sàng. Chỉ chọn xe thay thế khi khách hàng đã đồng ý. Nếu khách từ chối, <a href="index.php">kết thúc mà không lập hợp đồng</a>.</div><?php endif;?><?php if(!$cars):?><div class="alert error">Không có xe sẵn sàng. Không thể lập hợp đồng.</div><?php else:?><form method="post" action="contract_save.php" id="contractForm"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="request_id" value="<?=intval($id)?>"><label>Xe được xác nhận<select id="car" name="car_id" required><?php foreach($cars as $car):?><option value="<?=intval($car['id'])?>" data-rate="<?=esc($car['daily_rate'])?>" data-alt="<?=((int)$car['model_id']!==(int)$r['model_id'])?'1':'0'?>"><?=esc($car['car_code'].' · '.$car['model_name'].' · '.$car['license_plate'].' ('.money($car['daily_rate']).'/ngày)')?></option><?php endforeach;?></select></label><div id="altBox" class="alert warn" style="display:none"><label class="inline"><input type="checkbox" name="alternative_agreed" value="1" id="altAgreed"> Tôi xác nhận khách hàng đã đồng ý xe thay thế</label></div><div class="dategrid"><label>Ngày bắt đầu<input type="date" name="start_date" id="start" min="<?=date('Y-m-d')?>" value="<?=date('Y-m-d')?>" required></label><label>Ngày kết thúc<input type="date" name="end_date" id="end" min="<?=date('Y-m-d',strtotime('+1 day'))?>" value="<?=date('Y-m-d',strtotime('+1 day'))?>" required></label></div><div class="estimate"><span>Phí thuê dự kiến</span><strong id="total">—</strong><small id="days">Chọn thời gian thuê</small></div><button class="btn" <?=(!$profileOk || !$licenseOk || !$allowed || !$debtOk)?'disabled':''?>>Xác nhận lập hợp đồng</button><p class="muted">Hệ thống sẽ kiểm tra lại dữ liệu trước khi lưu hợp đồng và Rental.</p></form><?php endif;?></section></div>
<script src="assets/app.js"></script><?php page_end(); ?>
